function applyLanguage(){document.documentElement.lang=S.lang;$$('[data-i18n]').forEach(e=>e.textContent=t(e.dataset.i18n));$('#outerLanguage').textContent=S.lang.toUpperCase()+' ⌄';$('#searchButton').innerHTML=I('search')+t('search');$('#lockIcon').innerHTML=I('lock');$('#flashlightButton').innerHTML=I('flashlight');$('#cameraShortcut').innerHTML=I('camera');$('#signalIcon').innerHTML=I('signal');$('#wifiIcon').innerHTML=I('wifi');$('#notificationIcon').innerHTML=I('message');$('#copyrightYear').textContent=new Date().getFullYear();$('#homeIndicator').setAttribute('aria-label',S.locked?t('swipeUnlock'):t('home'));$('#statusTime').setAttribute('aria-label',t('notifications'));$('#controlButton').setAttribute('aria-label',t('controlCenter'));renderHome();updateClock();}
