function updateClock(){const n=new Date();const fmt=new Intl.DateTimeFormat(locale(),{timeZone:'Asia/Jakarta',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});const time=fmt.format(n).replace('.',':');$('#statusTime').textContent=time;$('#lockTime').textContent=time;$('#lockDate').textContent=n.toLocaleDateString(locale(),{timeZone:'Asia/Jakarta',weekday:'long',day:'numeric',month:'long'});if(S.app==='clock'&&S.clockTab==='world')$$('[data-clock-zone]').forEach(e=>e.textContent=n.toLocaleTimeString(locale(),{timeZone:e.dataset.clockZone,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}));}
function screenMode(){const s=$('#screenContent');s.classList.toggle('on-lock',S.locked);s.classList.toggle('on-home',!S.locked&&!S.app);$('#lockScreen').classList.toggle('is-hidden',!S.locked);$('#homeScreen').classList.toggle('is-hidden',S.locked||!!S.app);$('#appScreen').classList.toggle('is-hidden',S.locked||!S.app);$('#sleepScreen').classList.toggle('is-hidden',!S.sleep);$('#homeIndicator').setAttribute('aria-label',S.locked?t('swipeUnlock'):t('home'));}
function stopCamera(){if(cameraStream){cameraStream.getTracks().forEach(x=>x.stop());cameraStream=null}}
function unlock(target){S.locked=false;S.sleep=false;$('#lockScreen').style.transform='';$('#lockScreen').style.opacity='';$('#lockIcon').innerHTML=I('unlock');screenMode();beep();if(target)openApp(target)}
function remember(){if(S.app)S.scroll[S.app+':'+(S.detail||'')]=$('#appBody').scrollTop;}
function home(){remember();stopCamera();S.app=null;S.detail=null;S.backStack=[];closeOverlay();renderHome();screenMode();}
function lock(){remember();stopCamera();S.locked=true;S.app=null;S.detail=null;S.sleep=true;closeOverlay();screenMode()}
function openApp(key,detail=null,fromBack=false){if(!APPS[key])return;remember();stopCamera();if(S.locked)unlock();if(!fromBack&&S.app&&S.app===key)S.backStack.push(S.detail);else if(!fromBack)S.backStack=[];S.app=key;S.detail=detail;S.recent=[key,...S.recent.filter(x=>x!==key)].slice(0,8);closeOverlay();screenMode();renderApp();$('#appBody').scrollTop=S.scroll[key+':'+(detail||'')]||0;}
function back(){if(S.overlay){closeOverlay();return}if(S.detail!==null){S.detail=S.backStack.pop()??null;renderApp();return}home()}
function header(title,subtitle='',extra=''){return `<button data-action="back" aria-label="${t('back')}">${I('back')}</button><h2>${esc(title)}${subtitle?'<small>'+esc(subtitle)+'</small>':''}</h2>${extra}<button data-action="home" aria-label="${t('home')}">${I('home')}</button>`}
function renderApp(){if(!S.app)return;const key=S.app;$('#appHeader').innerHTML=header(appName(key));const b=$('#appBody');b.className='app-body';b.style.background='';if(window.SYSTEM_APPS?.[key]){$('#appHeader').innerHTML=header(appName(key),tx('PRATINJAU APLIKASI','APPLICATION PREVIEW','アプリのプレビュー','应用预览'));b.classList.add('system-app');b.innerHTML=SYSTEM_APPS[key].render(S.lang);return}const map={messages:renderMessages,career:renderCareer,photos:renderPhotos,notes:renderNotes,settings:renderSettings,contact:renderContact,hire:renderHire,instagram:renderInstagram,linkedin:renderLinkedin,chatgpt:renderAI,claude:renderAI,gemini:renderAI,dev:renderDev,calculator:renderCalculator,clock:renderClock,calendar:renderCalendar,weather:renderWeather,camera:renderCamera,files:renderFiles,safari:renderSafari,music:renderMusic};b.innerHTML=(map[key]||(()=>''))();if(['instagram','linkedin'].includes(key))b.classList.add('social-body');if(key==='dev'&&S.devPreview)runCode();if(key==='camera'&&cameraStream)$('#cameraVideo').srcObject=cameraStream;updateClock();}
function renderMessages(){if(S.detail){const s=C.stories.find(x=>x.id===S.detail);if(!s){S.detail=null;return renderMessages()}$('#appHeader').innerHTML=header(tr(s.title),tr(s.topic));let count=Math.min(S.progress[s.id]||6,s.messages.length);S.progress[s.id]=count;write('progress',S.progress);let msgs=s.messages.slice(0,count);const chosen=S.choices[s.id]||[];if(count>=s.messages.length)chosen.forEach(i=>{if(s.choices[i])msgs=msgs.concat(s.choices[i].messages)});return `<p class="chat-meta">${esc(tr(s.period))}<br>${esc(t('reconstruction'))}</p><div class="chat-bubbles">${msgs.map((m,i)=>`<div class="bubble-wrap ${m.role}"><span class="bubble-label">${m.role==='dandy'?'Dandy':esc(tr(C.labels.team))}</span><div class="bubble">${esc(tr(m.text))}</div></div>`).join('')}</div><div class="read-progress"><span style="width:${count/s.messages.length*100}%"></span></div><div class="story-controls">${count<s.messages.length?button(t('continue'),'continueStory','primary full',s.id)+button(t('readAll'),'readAll','secondary full',s.id):`<p class="small muted">${esc(tr(C.labels.explore))}</p>${s.choices.map((q,i)=>chosen.includes(i)?'':button(esc(tr(q.label)),'storyChoice','choice-card',s.id+':'+i)).join('')}${button(t('messages'),'storyList','secondary full')}`}</div>`}return `<p class="kicker">${tx('DANDY · PERCAKAPAN KERJA','DANDY · WORK CONVERSATIONS','DANDY · 仕事の会話','DANDY · 工作对话')}</p><h3>${t('messages')}</h3><p class="muted">${t('storyIntro')}</p><div class="thread-list">${C.stories.map((s,i)=>`<button class="thread" data-action="story" data-value="${s.id}"><span class="thread-avatar" style="background:${['#e3ede6','#e9dfd2','#e0e8f1','#e9e3d8','#e2e8e7','#dde9e5','#f0e4d6'][i]}">${I(['file','people','briefcase','layers','chart','code','gemini'][i])}</span><span class="thread-copy"><strong>${esc(tr(s.title))}</strong><p>${esc(tr(s.subtitle))}</p></span><span>${S.progress[s.id]?'': '<i class="unread" style="display:block"></i>'}</span></button>`).join('')}</div><p class="small muted">${esc(tr(C.labels.reconstruction))}</p>`}
function renderCareer(){if(S.detail){const c=C.career.find(x=>x.id===S.detail);if(c)return `<div class="career-detail"><p class="kicker">${esc(tr(c.phase))}</p><span class="career-year">${c.year||''}</span><h3>${esc(tr(c.role))}</h3><p class="muted">${esc(tr(c.company))}</p><span class="tag">${esc(tr(c.date))}</span><p>${esc(tr(c.summary))}</p><div class="divider"></div><p class="kicker">${t('skills')}</p><div class="skill-tags">${c.skills.map(s=>'<span>'+esc(tr(s))+'</span>').join('')}</div>${button(t('messages'),'openMessages','secondary full')}</div>`}const items=C.career.filter(c=>S.careerFilter==='all'||c.kind===S.careerFilter);return `<p class="kicker">2016 — ${tx('SEKARANG','PRESENT','現在','至今')}</p><h3>${t('journey')}</h3><p class="muted">${t('careerIntro')}</p><div class="segmented">${['all','work','education','milestone'].map(k=>button(t(k),'careerFilter',S.careerFilter===k?'active':'',k)).join('')}</div><div class="career-list">${items.map(c=>`<article class="career-item"><button data-action="careerDetail" data-value="${c.id}"><time>${esc(tr(c.date))}</time><strong>${esc(tr(c.role))}</strong><small>${esc(tr(c.company))}</small>${c.parallel?'<span class="tag">'+tx('Jalur paralel','Parallel role','並行する役割','并行角色')+'</span>':''}</button></article>`).join('')}</div>`}
