function roleWa(){const msg=tx(`Halo Dandy, saya tertarik membahas posisi ${selectedOfferName()} dengan ekspektasi gaji USD ${S.selectedOffer==='lead'?'3.500':'2.000'} per bulan dari portofolio Anda. Apakah bisa berdiskusi lebih lanjut?`,`Hi Dandy, I’d like to discuss the ${selectedOfferName()} role with a monthly salary expectation of USD ${S.selectedOffer==='lead'?'3,500':'2,000'} from your portfolio. Could we talk further?`,`Dandyさん、ポートフォリオの${selectedOfferName()}の役割について相談したいです。詳しくお話しできますか？`,`Dandy 你好，我想讨论作品集中 ${selectedOfferName()} 的岗位。方便进一步沟通吗？`);return 'https://wa.me/6285773700111?text='+encodeURIComponent(msg)}
function renderContact(){return `<div class="profile-hero"><img src="assets/dandy-portrait.png" alt="Dandy Aryo Putra"><h3>Dandy Aryo Putra</h3><p>${t('role')}</p><p>Tangerang · Indonesia</p></div><h3 style="font-size:22px">${t('contactMe')}</h3><p class="muted">${t('contactIntro')}</p>${S.selectedOffer?`<div class="card"><p class="kicker">${t('selectedRole')}</p><strong>${selectedOfferName()}</strong><p class="small">USD ${S.selectedOffer==='lead'?'3,500':'2,000'} ${t('perMonth')}</p></div>`:''}<div class="contact-actions">${ext(S.selectedOffer?roleWa():WA,t('whatsapp'),'primary whatsapp','message')}${button(t('copyNumber'),'copyNumber','secondary')}${button(t('saveContact'),'saveContact','secondary')}</div><div class="card contact-info"><span class="muted">WhatsApp</span><strong>+62 857 7370 0111</strong><div class="divider"></div>${ext(links.instagram,'@uandandy','secondary full','instagram')}<div style="height:8px"></div>${ext(links.linkedin,'Dandy Aryo · LinkedIn','secondary full','linkedin')}</div>`}
function offerData(k){const premium=k==='lead';return {title:premium?'Operations & Transformation':'Operations & Compliance',price:premium?'3,500':'2,000',intro:premium?tx('Memimpin kerja lintas fungsi dan membangun cara kerja yang lebih terhubung.','Lead cross-functional execution and build more connected ways of working.','部門を越えて実行を導き、つながる仕事の仕組みをつくる。','带领跨职能执行，建立更连贯的工作方式。'):tx('Mengelola operasi, kepatuhan, dan tindak lanjut dengan ritme kerja yang jelas.','Manage operations, compliance, and follow-up with a clear working rhythm.','運営、コンプライアンス、フォローアップを明確な流れで管理する。','以清晰节奏管理运营、合规与跟进。'),scope:premium?[tx('Menyelaraskan sales, engineering, produksi, SCM, dan koordinasi finance.','Align sales, engineering, production, SCM, and finance coordination.','営業、技術、生産、SCM、財務調整を連携。','协调销售、工程、生产、供应链及财务协作。'),tx('Meninjau kapasitas, prioritas proyek, risiko delivery, dan kinerja organisasi.','Review capacity, project priorities, delivery risks, and organizational performance.','能力、案件優先順位、納期リスク、組織の成果を確認。','审视产能、项目优先级、交付风险与组织绩效。'),tx('Mengembangkan sistem pengelolaan, pelaporan, serta kontrol lintas fungsi.','Develop management systems, reporting, and cross-functional controls.','管理システム、報告、部門間の管理を整備。','开发管理系统、报表及跨职能控制。')]:[tx('Mengelola fungsi atau unit operasi dan kesiapan dokumen.','Manage an operating function or unit and documentation readiness.','運営部門と文書整備を管理。','管理运营职能或业务单元及文件准备。'),tx('Menetapkan prioritas, penanggung jawab, dan tindak lanjut pekerjaan.','Set priorities, ownership, and follow-up for the work.','優先順位、担当、フォローアップを設定。','明确工作优先级、负责人和后续行动。'),tx('Merapikan proses, laporan, dan persyaratan pelanggan.','Improve processes, reporting, and customer requirement handling.','業務、報告、顧客要求への対応を改善。','改进流程、报告和客户要求的处理。')]}}
function renderHire(){if(S.detail){const d=offerData(S.detail);return `<div class="offer-detail"><div class="offer-card ${S.detail==='lead'?'premium':''}"><small>${t('salary')}</small><h3>${d.title}</h3><p>${d.intro}</p><div class="offer-price">$${d.price}<small>USD ${t('perMonth')}</small></div></div><h4>${t('scope')}</h4><ul>${d.scope.map(x=>'<li>'+x+'</li>').join('')}</ul><h4>${t('aiSupport')}</h4><div class="ai-team">${(S.detail==='lead'?[['chatgpt','Astra',tx('Analisis & perumusan masalah','Analysis & problem framing','分析と課題設定','分析与问题定义')],['gemini','Argon',tx('Alat kerja & otomasi','Tools & automation','ツールと自動化','工具与自动化')],['claude','Claude / Anthropic',tx('Telaah & pembanding','Review & second perspective','レビューと別の視点','审查与交叉比较')]]:[['chatgpt','Clarissa / ChatGPT',tx('Analisis, dokumen, dan pendampingan kerja','Analysis, documents, and work support','分析、文書、業務支援','分析、文档与工作支持')]]).map(([a,n,r])=>`<div class="ai-person">${I(APPS[a].icon)}<span><strong>${n}</strong><small>${r}</small></span></div>`).join('')}</div><p class="small muted">${tx('Asisten AI mendukung cara kerja saya; pembagian peran disesuaikan dengan kebutuhan perusahaan.','AI assistants support my workflow; their roles are tailored to the employer’s needs.','AIは私の仕事を支援し、役割は会社の必要に合わせます。','AI 助手支持我的工作方式，其分工将根据公司需要调整。')}</p><h4>${t('first90')}</h4>${[tx('01—30 · Pahami proses, orang, dan masalah yang paling mendesak.','01—30 · Understand processes, people, and the most urgent issues.','01—30 · 業務、人、最も急ぐ課題を理解。','01—30 · 了解流程、人员及最迫切的问题。'),tx('31—60 · Sepakati prioritas, jalankan perbaikan awal, dan rapikan kontrol.','31—60 · Agree priorities, start improvements, and strengthen controls.','31—60 · 優先順位に合意し、改善と管理を開始。','31—60 · 确定优先级，启动改进并完善控制。'),tx('61—90 · Evaluasi hasil, sesuaikan pendekatan, dan susun langkah berikutnya.','61—90 · Review results, adjust the approach, and plan next steps.','61—90 · 結果を確認し、方法を調整して次を計画。','61—90 · 评估结果，调整方法并规划下一步。')].map(p=>'<p class="small">'+p+'</p>').join('')}<p class="small muted">${t('salaryNote')}</p>${button(t('discuss'),'chooseOffer','primary full',S.detail)}</div>`}return `<p class="kicker">WORK WITH DANDY</p><h3>${t('hireIntro')}</h3><p class="muted small">${t('salary')}</p>${['ops','lead'].map(k=>{const d=offerData(k);return `<article class="offer-card ${k==='lead'?'premium':''}"><small>${k==='lead'?'CROSS-FUNCTIONAL LEADERSHIP':'OPERATIONS & GOVERNANCE'}</small><h3>${d.title}</h3><p>${d.intro}</p><span class="offer-badge">${I('gemini',12)}${k==='lead'?'3':'1'} ${t('aiSupport')}</span><div class="offer-price">$${d.price}<small>USD ${t('perMonth')}</small></div>${button(tx('Lihat lingkup posisi','Explore this role','役割の詳細','了解职位'),'offer','primary',k)}</article>`}).join('')}<p class="small muted">${t('salaryNote')}</p>`}
function renderInstagram(){if(S.detail){const i=Number(S.detail);return `<div class="social-header"><div class="row"><img src="assets/ig-0.jpg" width="30" height="30" style="border-radius:50%" alt="uandandy"><strong>uandandy</strong></div></div><img src="assets/ig-${i}.jpg" alt="Instagram @uandandy" style="width:100%;display:block"><div class="social-header">${ext('https://www.instagram.com/uandandy/p/'+igPosts[i-1]+'/',t('viewPost'),'primary full','instagram')}<p class="small muted">${t('profileSnapshot')}</p></div>`}return `<div class="social-header"><div class="ig-profile"><img src="assets/ig-0.jpg" alt="uandandy"><div class="ig-stats"><span><b>3,238</b><small>${t('followers')}</small></span><span><b>1,696</b><small>${t('following')}</small></span></div></div><p class="social-name">dandy</p><p class="social-handle">@uandandy</p>${ext(links.instagram,t('openProfile'),'primary full','instagram')}</div><div class="social-tabs">${I('grid')}${I('contact')}</div><div class="ig-grid">${igPosts.map((_,i)=>`<button data-action="igPost" data-value="${i+1}" aria-label="${t('photo')} ${i+1}"><img loading="lazy" src="assets/ig-${i+1}.jpg" alt="${t('photo')} @uandandy ${i+1}"></button>`).join('')}</div><p class="snapshot-note">${t('profileSnapshot')}</p>`}
function renderLinkedin(){return `<div class="linkedin-cover"></div><div class="linkedin-profile"><img src="assets/dandy-portrait.png" alt="Dandy Aryo"><h3>Dandy Aryo</h3><p>General Manager, Business Operations, Operational Excellence, Business Improvement and Strategy Execution</p><p class="muted">${tx('Area DKI Jakarta','Greater Jakarta','ジャカルタ首都圏','大雅加达地区')}</p><p style="color:#0a66c2">500+ ${tx('koneksi','connections','つながり','人脉')}</p>${ext(links.linkedin,t('openProfile'),'primary full','linkedin')}</div><div class="linkedin-section"><h4>${t('about')}</h4><p>${tx('Pengalaman lintas fungsi dalam business planning, operations, project governance, QHSE, perbaikan proses, dan kinerja organisasi. Minat pada industri pertambangan, energi, serta bisnis berbasis aset.','Cross-functional experience in business planning, operations, project governance, QHSE, process improvement, and organizational performance. Interested in mining, energy, and asset-intensive businesses.','事業計画、運営、プロジェクト管理、QHSE、業務改善、組織成果に関する部門横断の経験。鉱業、エネルギー、設備集約型事業に関心があります。','在业务规划、运营、项目治理、QHSE、流程改进和组织绩效方面拥有跨职能经验，关注矿业、能源及资产密集型业务。')}</p></div><div class="linkedin-section"><h4>${t('experience')}</h4>${[['General Manager','PT Surya Sealindo Teknologi'],['Owner','PT Multiguna Karya Tjipta'],['HSSE Management','PT Petrodrill Manufaktur Indonesia']].map(([r,c])=>`<div class="row" style="margin:18px 0">${I('briefcase',24)}<div><strong style="font-size:12px">${r}</strong><p class="small muted" style="margin:4px 0">${c}</p></div></div>`).join('')}</div><p class="snapshot-note">${t('profileSnapshot')}</p>`}
function aiAnswer(topic){const lines={about:tx('Saya Dandy. Latar saya dimulai dari perawatan pesawat, lalu MEP-HVAC, HR dan HSSE, sampai memimpin operasional. Yang saya bawa dari perjalanan itu: ketelitian teknis, kebiasaan memeriksa bukti, dan melihat hubungan antarbagian.','I’m Dandy. I started in aircraft maintenance, moved through MEP-HVAC, HR and HSSE, and into operations leadership. That journey shaped my technical discipline, habit of checking evidence, and cross-functional perspective.','Dandyです。航空機整備からMEP-HVAC、HR・HSSEを経て、運営の統括へ進みました。技術的な丁寧さ、証拠を確かめる習慣、部門間のつながりを見る視点を大切にしています。','我是 Dandy。从飞机维修开始，经历 MEP-HVAC、人力资源与 HSSE，逐步走向运营管理。这段历程让我重视技术严谨性、证据核实和跨部门联系。'),work:tx('Biasanya saya mulai dengan memastikan masalahnya apa. Kita punya fakta apa, bagian mana yang masih asumsi, dan siapa yang terdampak? Setelah itu baru tentukan prioritas, penanggung jawab, serta cara mengecek hasil. Di aplikasi Pesan, ada contoh alurnya untuk audit, tender, dan operasional.','I usually begin by defining the problem. What facts do we have, what are we assuming, and who is affected? Then I set priorities, ownership, and a way to check the result. Messages contains examples for audits, tenders, and operations.','まず課題を明確にします。事実は何か、仮定はどこか、誰に影響するか。その後、優先順位、担当、結果の確認方法を決めます。メッセージに具体例があります。','我通常先明确问题：有哪些事实，哪些还只是推测，会影响谁？随后确定优先级、负责人和验证结果的方法。“信息”中有审计、投标与运营的示例。'),systems:tx('CERDAS membantu melihat perjalanan pekerjaan. WMS menata persediaan. MITRA menghubungkan aktivitas lapangan dan pelaporan. HRIS berfokus pada administrasi SDM. SRMS mendukung pengadaan. Kamu bisa membuka ikon masing-masing untuk melihat pratinjau tampilannya dengan data ilustrasi.','CERDAS follows work progress. WMS organizes inventory. MITRA connects field activity and reporting. HRIS focuses on HR administration. SRMS supports procurement. Open their icons to explore locally reconstructed previews with illustrative data.','CERDASは仕事の進捗、WMSは在庫、MITRAは現場活動と報告、HRISは人事、SRMSは調達を支援します。各アイコンでサンプルデータのプレビューを見られます。','CERDAS 跟踪工作进展，WMS 管理库存，MITRA 连接现场活动与报告，HRIS 处理人事行政，SRMS 支持采购。打开各应用可查看使用示例数据的界面预览。'),career:tx('Perjalanannya dimulai pada 2016. Setelah aviasi dan operasi gedung, saya masuk HR di Petrodrill pada 2022, berkembang ke kepemimpinan HSSE, lalu bergabung dengan SST pada Maret 2025. Sejak November 2025 saya menjalankan peran General Manager Operasional. Detail setiap langkah ada di Riwayat.','My journey started in 2016. After aviation and building operations, I joined Petrodrill in HR in 2022, grew into HSSE leadership, and joined SST in March 2025. I have served as General Manager, Operations since November 2025. Career has the individual milestones.','2016年に始まり、航空と建物運営を経て、2022年にPetrodrillのHRへ。その後HSSEを率い、2025年3月にSSTへ入社。2025年11月から運営統括を担当しています。','职业历程始于 2016 年。经过航空与楼宇运营，2022 年进入 Petrodrill 从事 HR，逐步承担 HSSE 领导工作，2025 年 3 月加入 SST，自 2025 年 11 月担任运营总经理。')};return lines[topic]||t('aiFallback')}
function renderAI(){const k=S.app;const history=S.ai[k]||[];const prompt={chatgpt:tx('Mau kenalan lebih jauh?','Where shall we start?','何からお話ししましょう？','从哪里聊起？'),claude:tx('Mari lihat persoalannya.','Let’s look at the problem.','課題を一緒に見てみましょう。','一起看看问题。'),gemini:tx('Ada yang ingin kamu jelajahi?','What would you like to explore?','何を知りたいですか？','你想探索什么？')}[k];return `<div class="ai-screen ${k}-screen"><p class="ai-brand-note">${t('aiCurated')}</p><div class="ai-welcome">${I(APPS[k].icon,45)}<h3>${prompt}</h3></div><div class="ai-chips">${[['about','aiAbout'],['work','aiWork'],['systems','aiSystems'],['career','aiCareer']].map(([v,l])=>button(t(l),'aiTopic','',v)).join('')}</div>${history.map(h=>`<div class="ai-question">${esc(h.q)}</div><div class="ai-answer">${esc(aiAnswer(h.topic))}</div>`).join('')}<form class="ai-compose" id="aiForm"><input id="aiQuestion" aria-label="${t('aiInput')}" placeholder="${t('aiInput')}" maxlength="500"><button aria-label="${t('send')}">${I('arrow')}</button></form></div>`}
function renderDev(){return `<p class="kicker">DANDY / PLAYGROUND</p><div class="segmented">${button(t('code'),'devMode',!S.devPreview?'active':'','code')}${button(t('preview'),'devMode',S.devPreview?'active':'','preview')}</div>${S.devPreview?'<iframe class="code-preview" id="codePreview" sandbox="allow-scripts" title="Isolated code preview"></iframe>':`<div class="code-tabs">${['html','css','js'].map(k=>button(k==='html'?'index.html':k==='css'?'style.css':'script.js','devTab',S.devTab===k?'active':'',k)).join('')}</div><textarea class="code-editor" id="codeEditor" spellcheck="false" aria-label="${t('code')}">${esc(devFiles[S.devTab])}</textarea>`}<div class="button-row">${button(I('play',14)+t('run'),'runCode')}${button(t('resetCode'),'resetCode','secondary')}</div><p class="small muted">${t('devNote')}</p>`}
function saveCode(){if($('#codeEditor')){devFiles[S.devTab]=$('#codeEditor').value;write('devFiles',devFiles)}}
function runCode(){if(!$('#codePreview'))return;const html=devFiles.html.replace(/<\/script/gi,'<\\/script');const script=devFiles.js.replace(/<\/script/gi,'<\\/script');$('#codePreview').srcdoc=`<!doctype html><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; img-src data:"><style>${devFiles.css.replace(/<\/style/gi,'')}</style>${html}<script>${script}<\/script>`}
function renderCalculator(){return `<div class="calculator-display" id="calcDisplay">${esc(calcValue)}</div><div class="calculator-grid">${['AC','±','%','÷','7','8','9','×','4','5','6','−','1','2','3','+','0','.','='].map(v=>`<button class="${'÷×−+='.includes(v)?'op':['AC','±','%'].includes(v)?'utility':''} ${v==='0'?'wide':''}" data-action="calc" data-value="${v}">${v}</button>`).join('')}</div>`}
function computeCalc(expr){const tokens=expr.match(/(?:\d*\.\d+|\d+)|[+\-*/]/g)||[];if(tokens.join('')!==expr||!tokens.length)return NaN;let values=[],ops=[],expectNumber=true;let sign=1;const apply=()=>{let b=values.pop(),a=values.pop(),o=ops.pop();values.push(o==='+'?a+b:o==='-'?a-b:o==='*'?a*b:a/b)};const rank=o=>'+-'.includes(o)?1:2;for(const tok of tokens){if(expectNumber&&tok==='-'){sign*=-1;continue}if(!isNaN(Number(tok))){if(!expectNumber)return NaN;values.push(Number(tok)*sign);sign=1;expectNumber=false}else{if(expectNumber)return NaN;while(ops.length&&rank(ops.at(-1))>=rank(tok))apply();ops.push(tok);expectNumber=true}}if(expectNumber)return NaN;while(ops.length)apply();return values[0]}
function calc(v){if(v==='AC'){calcExpression='';calcValue='0'}else if(v==='='){const n=computeCalc(calcExpression);calcValue=Number.isFinite(n)?String(Number(n.toPrecision(10))):'Error';calcExpression=calcValue==='Error'?'':calcValue}else if(v==='±'){let n=Number(calcValue);if(Number.isFinite(n)){calcValue=String(-n);calcExpression=calcValue}}else if(v==='%'){let n=Number(calcValue);if(Number.isFinite(n)){calcValue=String(n/100);calcExpression=calcValue}}else{const op={'÷':'/','×':'*','−':'-'}[v]||v;if(calcExpression.length>45)return;if('+-*/'.includes(op)&&/[+\-*/]$/.test(calcExpression))calcExpression=calcExpression.slice(0,-1);calcExpression+=op;calcValue=calcExpression.replaceAll('*','×').replaceAll('/','÷')}$('#calcDisplay').textContent=calcValue}
const duration=ms=>{const s=Math.floor(Math.max(ms,0)/1000);return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')};
function renderClock(){let html=`<div class="segmented">${[['world','worldClock'],['stopwatch','stopwatch'],['timer','timer']].map(([v,l])=>button(t(l),'clockTab',v===S.clockTab?'active':'',v)).join('')}</div>`;if(S.clockTab==='world')return html+[['Jakarta','Asia/Jakarta'],['Singapore','Asia/Singapore'],['Tokyo','Asia/Tokyo'],['London','Europe/London']].map(([n,z])=>`<div class="clock-city"><strong>${n}</strong><span data-clock-zone="${z}"></span></div>`).join('');if(S.clockTab==='stopwatch')return html+`<div class="clock-digital" id="stopwatchDisplay">${duration(stopwatchElapsed+(stopwatchRunning?Date.now()-stopwatchStart:0))}</div><div class="button-row">${button(stopwatchRunning?t('pause'):t('start'),'stopwatchToggle')}${button('↺','stopwatchReset','secondary')}</div>`;return html+`<div class="clock-digital" id="timerDisplay">${duration(timerRunning?timerEnd-Date.now():timerRemaining)}</div><label class="timer-input"><input id="timerMinutes" type="number" min="1" max="180" value="5" aria-label="${t('minutes')}"><span class="small">${t('minutes')}</span></label><div class="button-row">${button(timerRunning?t('pause'):t('start'),'timerToggle')}${button('↺','timerReset','secondary')}</div>`}
function renderCalendar(){const now=new Date(),n=new Date(now.getFullYear(),now.getMonth()+S.calendarOffset,1);const start=(n.getDay()+6)%7,days=new Date(n.getFullYear(),n.getMonth()+1,0).getDate();return `<div class="row-between calendar-controls"><button data-action="month" data-value="-1">${I('back')}</button><strong>${n.toLocaleDateString(locale(),{month:'long',year:'numeric'})}</strong><button data-action="month" data-value="1">${I('chevron')}</button></div><div class="calendar-grid">${Array.from({length:7},(_,i)=>`<span class="weekday">${new Date(2024,0,1+i).toLocaleDateString(locale(),{weekday:'short'})}</span>`).join('')}${'<span></span>'.repeat(start)}${Array.from({length:days},(_,i)=>`<span class="${i+1===now.getDate()&&n.getMonth()===now.getMonth()&&n.getFullYear()===now.getFullYear()?'today':''}">${i+1}</span>`).join('')}</div><div class="card"><p class="kicker">${t('today')}</p><p class="small muted">${t('noSchedule')}</p></div>${button(t('journey'),'openCareer','secondary full')}`}
function renderWeather(){return `<div class="weather-hero"><h3>Tangerang</h3>${I('weather',80)}<strong>29°</strong><p>${t('weatherSunny')}</p></div><p class="small muted">${t('weatherDemo')}</p><div class="card"><div class="weather-hours">${['08:00','10:00','12:00','14:00','16:00'].map((h,i)=>`<span>${h}${I('weather')} ${[27,29,31,30,29][i]}°</span>`).join('')}</div></div><div class="card"><div class="row-between"><span class="small">${tx('Kelembapan','Humidity','湿度','湿度')}</span><strong>72%</strong></div><div class="divider"></div><div class="row-between"><span class="small">${tx('Angin','Wind','風','风速')}</span><strong>8 km/h</strong></div></div>`}
function renderCamera(){return `<div class="camera-view">${cameraStream?'<video id="cameraVideo" autoplay muted playsinline></video>':`<div class="camera-placeholder">${I('camera',55)}<p>${t('camera')}</p></div>`}<div class="camera-grid"></div></div>${cameraStream?'<button class="shutter" data-action="capture" aria-label="'+t('capture')+'"></button>':button(t('enableCamera'),'enableCamera','primary full')}<p class="small muted">${t('cameraNotice')}</p>`}
async function enableCamera(){try{cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});renderApp();island(t('camera'))}catch{toast(t('cameraUnavailable'))}}
function capture(){const video=$('#cameraVideo');if(!video||!video.videoWidth)return;const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);captures.push(canvas.toDataURL('image/jpeg',.85));toast(t('captureSaved'));beep()}
function profileText(){return 'Dandy Aryo Putra\n'+t('role')+'\n\n'+C.career.map(c=>tr(c.date)+'\n'+tr(c.role)+' — '+tr(c.company)+'\n'+tr(c.summary)+'\n').join('\n')+'\nWhatsApp: +62 857 7370 0111\n'+links.linkedin+'\n'+links.instagram}
function renderFiles(){if(S.detail==='profile')return `<h3>${t('profileFile')}</h3><div class="card"><p style="white-space:pre-line">${esc(profileText())}</p></div>${button(t('download')+' .txt','downloadProfile','primary full')}`;return `<h3>${t('files')}</h3><p class="kicker">DANDY / PUBLIC</p><button class="file-row" data-action="profileFile">${I('file')}<span><strong>${t('profileFile')}</strong><small>TXT · ${t('career')}</small></span></button><button class="file-row" data-open="photos">${I('folder')}<span><strong>${t('certificates')}</strong><small>${t('albums')}</small></span></button><button class="file-row" data-open="dev">${I('code')}<span><strong>Portfolio / Playground</strong><small>HTML · CSS · JavaScript</small></span></button><button class="file-row" data-open="career">${I('briefcase')}<span><strong>${t('journey')}</strong><small>2016—2026</small></span></button>`}
function renderSafari(){return `<h3>${t('favourites')}</h3><form class="search-field" id="browserForm">${I('search')}<input id="browserAddress" placeholder="https://…" aria-label="URL"><button style="background:none;color:var(--blue)">${I('arrow',18)}</button></form><div class="browser-favourites">${[['GitHub',links.github,'code'],['Instagram',links.instagram,'instagram'],['LinkedIn',links.linkedin,'linkedin'],['ChatGPT','https://chatgpt.com','chatgpt'],['Claude','https://claude.ai','claude'],['Gemini','https://gemini.google.com','gemini']].map(([n,u,i])=>`<a href="${u}" target="_blank" rel="noopener noreferrer"><span>${I(i,30)}</span>${n}</a>`).join('')}</div><p class="small muted" style="margin-top:30px">${tx('Tautan dibuka di tab browser agar kamu bisa memakai situs aslinya.','Links open in a browser tab so you can use the original website.','リンクはブラウザーのタブで開きます。','链接会在浏览器标签页打开原网站。')}</p>`}
function renderMusic(){return `<div class="music-art"><strong>${t('ambient')}</strong></div><h3 style="font-size:21px">Quiet Hours</h3><p class="muted small">DANDY / FOCUS SESSION</p><div class="music-meter"><span></span></div><div class="music-controls"><button data-action="music" aria-label="${musicPlaying?t('pause'):t('play')}">${I(musicPlaying?'pause':'play')}</button></div><label class="setting-row"><span>${I('volume')}${t('volume')}</span><input type="range" min="0" max="100" value="${S.prefs.volume}" data-pref="volume" aria-label="${t('volume')}"></label><p class="small muted">${t('ambientNote')}</p>`}
function getAudio(){if(!audioContext)audioContext=new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();return audioContext}
function beep(){if(!S.prefs.sound)return;try{const c=getAudio(),o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.value=540;g.gain.setValueAtTime(.025*S.prefs.volume/100,c.currentTime);g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+.08);o.connect(g).connect(c.destination);o.start();o.stop(c.currentTime+.08)}catch{}}
function toggleMusic(){if(musicPlaying){ambientNodes.forEach(n=>{try{n.o.stop()}catch{}});ambientNodes=[];musicPlaying=false}else{try{const c=getAudio();[130.81,196,261.63].forEach((f,i)=>{const o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.value=f;g.gain.value=.018*S.prefs.volume/100/(i+1);o.connect(g).connect(c.destination);o.start();ambientNodes.push({o,g,i})});musicPlaying=true;island('Quiet Hours')}catch{toast(tx('Audio tidak tersedia.','Audio unavailable.','音声を利用できません。','音频不可用。'))}}if(S.app==='music')renderApp();if(S.overlay==='controls')openOverlay('controls')}
function download(name,text,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
function overlayHead(title){return `<div class="overlay-header"><h3>${title}</h3><button data-action="closeOverlay" aria-label="${t('close')}">${I('close')}</button></div>`}
function openOverlay(type){S.overlay=type;const o=$('#overlay');o.classList.remove('is-hidden');if(type==='controls'){o.innerHTML=overlayHead(t('controlCenter'))+`<div class="control-grid"><div class="control-tile"><div class="connectivity-grid"><span>${I('airplane')}</span><span>${I('signal')}</span><span>${I('wifi')}</span><span>${I('bluetooth')}</span></div><small>${tx('INDIKATOR SIMULASI','SIMULATED INDICATORS','シミュレーション表示','模拟指示')}</small></div><button class="control-tile" data-action="music">${I(musicPlaying?'pause':'play')}<strong>Quiet Hours</strong><small>${musicPlaying?t('pause'):t('start')}</small></button><button class="control-tile ${S.prefs.focus?'active':''}" data-action="toggleFocus">${I('moon')}<strong>${t('focus')}</strong></button><button class="control-tile ${S.prefs.dark?'active':''}" data-action="toggleDark">${I('sun')}<strong>${t('darkMode')}</strong></button><label class="control-slider">${I('sun')}<input type="range" min="15" max="100" value="${S.prefs.brightness}" data-pref="brightness" aria-label="${t('brightness')}"></label><label class="control-slider">${I('volume')}<input type="range" min="0" max="100" value="${S.prefs.volume}" data-pref="volume" aria-label="${t('volume')}"></label></div><div class="control-bottom"><button data-action="flashlight" aria-label="${t('brightness')}">${I('flashlight')}</button><button data-open="clock" aria-label="${t('clock')}">${I('clock')}</button><button data-open="calculator" aria-label="${t('calculator')}">${I('calculator')}</button><button data-open="camera" aria-label="${t('camera')}">${I('camera')}</button></div><p>${t('virtualNote')}</p>`}else if(type==='notifications'){o.innerHTML=overlayHead(t('notifications'))+C.stories.slice(0,4).map(s=>`<button class="control-tile" style="width:100%;margin-bottom:12px;min-height:80px" data-action="notificationStory" data-value="${s.id}"><strong>${esc(tr(s.title))}</strong><p>${esc(tr(s.subtitle))}</p></button>`).join('')}else if(type==='recent'){o.innerHTML=overlayHead(t('recentApps'))+`<div class="recent-grid">${S.recent.length?S.recent.map(k=>`<button class="recent-card" data-open="${k}">${icon(k)}<span><strong>${esc(appName(k))}</strong><small>${t('openApp')}</small></span></button>`).join(''):'<p>'+t('noRecent')+'</p>'}</div>`}else if(type==='search'){o.innerHTML=overlayHead(t('search'))+`<div class="search-field">${I('search')}<input id="spotlightInput" placeholder="${t('search')}" aria-label="${t('search')}"></div><div class="search-results" id="searchResults"></div>`;renderSearch('');setTimeout(()=>$('#spotlightInput')?.focus(),50)}else if(type==='language'){o.innerHTML=overlayHead(t('language'))+[['id','Bahasa Indonesia'],['en','English'],['ja','日本語'],['zh','简体中文']].map(([v,n])=>`<button class="recent-card" data-action="language" data-value="${v}" style="margin-bottom:12px;width:100%;min-height:65px">${v===S.lang?I('check'):I('globe')}<strong>${n}</strong></button>`).join('')}else if(type==='flashlight'){o.style.background='#fff';o.style.color='#222';o.innerHTML=overlayHead(tx('Senter virtual','Virtual flashlight','画面ライト','虚拟手电筒'))+`<p style="color:#555">${tx('Lampu layar untuk ponsel virtual.','Screen light for the virtual phone.','仮想スマホの画面ライトです。','虚拟手机的屏幕灯光。')}</p>`}else if(type==='reset'){o.innerHTML=overlayHead(t('reset'))+`<p>${tx('Hanya progres percakapan di browser ini yang akan diulang.','Only conversation progress in this browser will be reset.','このブラウザーの会話進捗のみリセットします。','仅重置本浏览器的对话进度。')}</p>${button(t('reset'),'confirmReset','primary full')}`}}
function closeOverlay(){S.overlay=null;$('#overlay').classList.add('is-hidden');$('#overlay').style.background='';$('#overlay').style.color='';}
function renderSearch(q){const box=$('#searchResults');if(!box)return;const needle=q.toLocaleLowerCase();const keys=Object.keys(APPS).filter(k=>(appName(k)+' '+k).toLocaleLowerCase().includes(needle));const careers=q.length>1?C.career.filter(c=>(tr(c.company)+' '+tr(c.role)).toLocaleLowerCase().includes(needle)).slice(0,5):[];box.innerHTML=keys.map(k=>`<button class="search-result" data-open="${k}">${icon(k)}<span>${esc(appName(k))}</span></button>`).join('')+careers.map(c=>`<button class="search-result" data-action="searchCareer" data-value="${c.id}">${I('briefcase')}<span>${esc(tr(c.role))}<small style="display:block;opacity:.6;margin-top:4px">${esc(tr(c.company))}</small></span></button>`).join('');if(!keys.length&&!careers.length)box.innerHTML='<p>'+t('emptySearch')+'</p>'}
function setLanguage(v){if(!LANGS.includes(v))return;remember();S.lang=v;write('lang',v);applyLanguage();if(S.app){renderApp();$('#appBody').scrollTop=S.scroll[S.app+':'+(S.detail||'')]||0}if(S.overlay)openOverlay(S.overlay)}
function setPreference(k,v){S.prefs[k]=v;applyPrefs();if(k==='volume')ambientNodes.forEach(n=>n.g.gain.value=.018*v/100/(n.i+1));}
document.addEventListener('input',e=>{if(e.target.dataset.pref){let k=e.target.dataset.pref,v=e.target.type==='checkbox'?e.target.checked:e.target.type==='range'?Number(e.target.value):e.target.value;setPreference(k,v)}if(e.target.id==='spotlightInput')renderSearch(e.target.value);if(e.target.id==='codeEditor')saveCode()});
document.addEventListener('change',e=>{if(e.target.id==='languageSelect')setLanguage(e.target.value);if(e.target.dataset.pref&&e.target.tagName==='SELECT')setPreference(e.target.dataset.pref,e.target.value)});
document.addEventListener('submit',e=>{if(e.target.id==='aiForm'){e.preventDefault();let q=$('#aiQuestion').value.trim();if(!q)return;let topic=/cerdas|wms|mitra|hris|srms|sistem|system|システム|系统/i.test(q)?'systems':/karier|career|riwayat|経歴|职业/i.test(q)?'career':/masalah|audit|problem|solve|課題|问题/i.test(q)?'work':/dandy|siapa|who|誰|你是/i.test(q)?'about':'other';(S.ai[S.app]??=[]).push({q,topic});renderApp();$('#appBody').scrollTop=$('#appBody').scrollHeight}else if(e.target.id==='browserForm'){e.preventDefault();let val=$('#browserAddress').value.trim();try{const u=new URL(/^https?:\/\//.test(val)?val:'https://'+val);if(['http:','https:'].includes(u.protocol))window.open(u.href,'_blank','noopener,noreferrer')}catch{toast('URL?')}}});
document.addEventListener('click',async e=>{const open=e.target.closest('[data-open]');if(open){openApp(open.dataset.open);return}const a=e.target.closest('[data-action]');if(!a)return;const v=a.dataset.value,action=a.dataset.action;switch(action){case'home':home();break;case'back':back();break;case'page':S.page=Number(v);renderHome();break;case'closeOverlay':closeOverlay();break;case'language':setLanguage(v);closeOverlay();break;case'story':openApp('messages',v);break;case'notificationStory':unlock();openApp('messages',v);break;case'storyList':openApp('messages');break;case'continueStory':{const previous=$('#appBody').scrollTop;S.progress[v]=(S.progress[v]||6)+4;write('progress',S.progress);renderApp();$('#appBody').scrollTop=previous+200;break}case'readAll':S.progress[v]=999;write('progress',S.progress);renderApp();break;case'storyChoice':{const [id,i]=v.split(':');(S.choices[id]??=[]).push(Number(i));write('choices',S.choices);renderApp();$('#appBody').scrollTop=$('#appBody').scrollHeight;break}case'careerFilter':S.careerFilter=v;renderApp();break;case'careerDetail':openApp('career',v);break;case'searchCareer':unlock();openApp('career',v);break;case'openCareer':openApp('career');break;case'openMessages':openApp('messages');break;case'photoFilter':S.photoAlbum=v;renderApp();break;case'photo':openApp('photos','photo:'+v);break;case'certificate':openApp('photos','certificate:'+v);break;case'album':openApp('photos','album:'+v);break;case'zoomPhoto':{const p=$('.photo-view');p.style.transform=p.style.transform?'':'scale(1.35)';break}case'saveNote':write('note',$('#noteEditor').value);toast(t('saved'));break;case'offer':openApp('hire',v);break;case'chooseOffer':S.selectedOffer=v;openApp('contact');break;case'copyNumber':try{await navigator.clipboard.writeText('+6285773700111');toast(t('copied'))}catch{toast('+62 857 7370 0111')}break;case'saveContact':download('Dandy-Aryo-Putra.vcf','BEGIN:VCARD\nVERSION:3.0\nFN:Dandy Aryo Putra\nTEL;TYPE=CELL:+6285773700111\nURL:https://www.linkedin.com/in/dandyaryo\nEND:VCARD','text/vcard');break;case'igPost':openApp('instagram',v);break;case'aiTopic':{const q={about:t('aiAbout'),work:t('aiWork'),systems:t('aiSystems'),career:t('aiCareer')}[v];(S.ai[S.app]??=[]).push({q,topic:v});renderApp();$('#appBody').scrollTop=$('#appBody').scrollHeight;break}case'devTab':saveCode();S.devTab=v;renderApp();break;case'devMode':saveCode();S.devPreview=v==='preview';renderApp();break;case'runCode':saveCode();S.devPreview=true;renderApp();break;case'resetCode':devFiles=JSON.parse(JSON.stringify(defaults));write('devFiles',devFiles);S.devPreview=false;renderApp();break;case'calc':calc(v);break;case'clockTab':S.clockTab=v;renderApp();break;case'stopwatchToggle':if(stopwatchRunning){stopwatchElapsed+=Date.now()-stopwatchStart;stopwatchRunning=false}else{stopwatchStart=Date.now();stopwatchRunning=true}renderApp();break;case'stopwatchReset':stopwatchRunning=false;stopwatchElapsed=0;renderApp();break;case'timerToggle':if(timerRunning){timerRemaining=Math.max(0,timerEnd-Date.now());timerRunning=false}else{timerRemaining=timerRemaining||Math.min(180,Math.max(1,Number($('#timerMinutes').value)||5))*60000;timerEnd=Date.now()+timerRemaining;timerRunning=true}renderApp();break;case'timerReset':timerEnd=0;timerRemaining=0;timerRunning=false;renderApp();break;case'month':S.calendarOffset+=Number(v);renderApp();break;case'enableCamera':await enableCamera();break;case'capture':capture();break;case'profileFile':openApp('files','profile');break;case'downloadProfile':download('Dandy-Aryo-Putra-Profile-'+S.lang+'.txt',profileText());break;case'music':toggleMusic();break;case'toggleFocus':setPreference('focus',!S.prefs.focus);openOverlay('controls');toast(S.prefs.focus?t('focusOn'):t('focusOff'));break;case'toggleDark':setPreference('dark',!S.prefs.dark);openOverlay('controls');break;case'flashlight':openOverlay('flashlight');break;case'resetProgress':openOverlay('reset');break;case'confirmReset':S.progress={};S.choices={};write('progress',{});write('choices',{});closeOverlay();toast(t('resetDone'));break;}});
$('#quickAccess').addEventListener('click',()=>{unlock();openApp('contact')});$('#outerLanguage').addEventListener('click',()=>openOverlay('language'));$('#controlButton').addEventListener('click',()=>openOverlay('controls'));$('#statusTime').addEventListener('click',()=>openOverlay('notifications'));$('#searchButton').addEventListener('click',()=>openOverlay('search'));$('#homeIndicator').addEventListener('click',e=>{if(e.detail===0&&S.locked){unlock();return}if(!S.locked)home();else toast(t('swipeUnlock'))});$('#lockNotification').addEventListener('click',()=>toast(t('swipeUnlock')));$('#powerButton').addEventListener('click',()=>{if(S.sleep){S.sleep=false;screenMode()}else lock()});$('#sleepScreen').addEventListener('click',()=>{S.sleep=false;screenMode()});$('#actionButton').addEventListener('click',()=>{setPreference('focus',!S.prefs.focus);toast(S.prefs.focus?t('focusOn'):t('focusOff'))});$('#volumeUp').addEventListener('click',()=>{setPreference('volume',Math.min(100,S.prefs.volume+10));toast(t('volume')+' '+S.prefs.volume+'%')});$('#volumeDown').addEventListener('click',()=>{setPreference('volume',Math.max(0,S.prefs.volume-10));toast(t('volume')+' '+S.prefs.volume+'%')});$('#flashlightButton').addEventListener('click',()=>openOverlay('flashlight'));$('#cameraShortcut').addEventListener('click',()=>{unlock();openApp('camera')});
let gesture=null,suppressClickUntil=0;
$('#screen').addEventListener('pointerdown',e=>{if(e.button!==0||S.sleep)return;const rect=$('#screen').getBoundingClientRect(),y=e.clientY-rect.top,x=e.clientX-rect.left;let type=null;if(e.target.closest('#gestureZone'))type='bottom';else if(S.locked&&!S.overlay&&!e.target.closest('button'))type='unlock';else if(y<54&&!S.overlay)type=x>rect.width*.62?'control':'notification';else if(!S.locked&&!S.app&&!S.overlay&&e.target.closest('#homePages'))type='home';if(!type)return;gesture={id:e.pointerId,x:e.clientX,y:e.clientY,time:Date.now(),type,dx:0,dy:0};if(type==='unlock'||type==='bottom')e.target.setPointerCapture(e.pointerId);});
$('#screen').addEventListener('pointermove',e=>{if(!gesture||gesture.id!==e.pointerId)return;gesture.dx=e.clientX-gesture.x;gesture.dy=e.clientY-gesture.y;if((gesture.type==='unlock'||gesture.type==='bottom')&&S.locked&&gesture.dy<0){$('#lockScreen').style.transition='none';$('#lockScreen').style.transform=`translateY(${gesture.dy*.8}px)`;$('#lockScreen').style.opacity=String(Math.max(.2,1+gesture.dy/600));}});
function finishGesture(e){if(!gesture||gesture.id!==e.pointerId)return;const g=gesture;gesture=null;$('#lockScreen').style.transition='';const elapsed=Date.now()-g.time;if(Math.abs(g.dx)>15||Math.abs(g.dy)>15)suppressClickUntil=Date.now()+250;if(g.type==='unlock'||g.type==='bottom'){if(g.dy<-65){if(S.locked)unlock();else if(S.overlay)closeOverlay();else if(elapsed>450&&g.dy<-95)openOverlay('recent');else home()}else{$('#lockScreen').style.transform='';$('#lockScreen').style.opacity=''}}else if(g.type==='home'){if(Math.abs(g.dx)>55&&Math.abs(g.dx)>Math.abs(g.dy)){S.page=Math.max(0,Math.min(homepage.length-1,S.page+(g.dx<0?1:-1)));renderHome()}else if(g.dy>70)openOverlay('search')}else if(g.dy>45)openOverlay(g.type==='control'?'controls':'notifications');}
$('#screen').addEventListener('pointerup',finishGesture);$('#screen').addEventListener('pointercancel',e=>{if(!gesture)return;gesture=null;$('#lockScreen').style.transition='';$('#lockScreen').style.transform='';$('#lockScreen').style.opacity=''});$('#screen').addEventListener('click',e=>{if(Date.now()<suppressClickUntil){e.stopPropagation();e.preventDefault()}},true);
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(e.key==='Escape'){e.preventDefault();S.overlay?closeOverlay():S.app?back():lock()}else if(e.key==='Enter'&&S.locked){e.preventDefault();unlock()}else if(e.key==='ArrowRight'&&!S.app&&!S.locked){S.page=1;renderHome()}else if(e.key==='ArrowLeft'&&!S.app&&!S.locked){S.page=0;renderHome()}});
setInterval(()=>{updateClock();if($('#stopwatchDisplay'))$('#stopwatchDisplay').textContent=duration(stopwatchElapsed+(stopwatchRunning?Date.now()-stopwatchStart:0));if($('#timerDisplay'))$('#timerDisplay').textContent=duration(timerRunning?timerEnd-Date.now():timerRemaining);if(timerRunning&&timerEnd<=Date.now()){timerRunning=false;timerRemaining=0;toast(t('timerDone'));island(t('timerDone'));beep();if(S.app==='clock')renderApp()}},1000);
if(window.SYSTEM_STYLE){const s=document.createElement('style');s.textContent=window.SYSTEM_STYLE;document.head.appendChild(s)}
applyLanguage();applyPrefs();screenMode();
